  const rotations = plan.rotations || ALL_ROTATIONS;
  for (let r = 0; r <= searchRadius; r++) {
    for (let dy = -r; dy <= r; dy++) {
      for (let dx = -r; dx <= r; dx++) {
        if (Math.abs(dx) !== r && Math.abs(dy) !== r) continue;
        const anchorX = targetX + dx;
        const anchorY = targetY + dy;
